import { writeFileSync } from "node:fs";

function deskBlock(c) {
  return `  {
    id: ${JSON.stringify(c.id)},
    title: ${JSON.stringify(c.title)},
    kicker: ${JSON.stringify(c.kicker)},
    subtitle: ${JSON.stringify(c.subtitle)},
    lede: ${JSON.stringify(c.lede)},
    summary: ${JSON.stringify(c.summary)},
    body: ${JSON.stringify(c.body)},
    evidence: ${JSON.stringify(c.evidence)},
    sources: ${JSON.stringify(c.sources, null, 6).replace(/\n/g, "\n    ")},
    lat: ${c.lat},
    lng: ${c.lng},
    place: ${JSON.stringify(c.place)},
    country: ${JSON.stringify(c.country)},
    year: ${c.year},
  }`;
}

const files = [
  { id: "project-sign", title: "Project Sign", kicker: "1948", subtitle: "U.S. Air Force · first saucer desk", lede: "The Air Force’s first UFO office briefly wrote that the objects could be interplanetary — then the estimate vanished.", summary: "Project Sign at Wright-Patterson collected 1948 sightings and, according to later officers, drafted an Estimate of the Situation concluding the objects were interplanetary. The estimate was rejected and destroyed as a staff paper. Sign became Grudge. The missing estimate is the original ‘buried conclusion’ story of the U.S. program.", body: "What survives are the case cards, the staff memory of the estimate, and the rapid tone shift into Grudge’s debunking posture. No authenticated copy of the Estimate has been released from a vault. The file still matters because it shows how early the Air Force treated saucers as an intelligence problem, not a joke.", evidence: "Sign records are in the National Archives Blue Book predecessor files. The Estimate itself is attested by participants, not by a surviving signed original.", sources: ["Ruppelt, The Report on Unidentified Flying Objects", "USAF Project Sign records, NARA"], lat: 39.823, lng: -84.049, place: "Wright-Patterson AFB, Ohio", country: "USA", year: 1948 },
  { id: "estimate-of-situation", title: "Estimate of the Situation", kicker: "1948", subtitle: "Air Force intelligence · lost staff paper", lede: "A 1948 Air Force estimate reportedly called flying saucers interplanetary. The paper was killed.", summary: "Officers around Project Sign later described a Top Secret Estimate of the Situation that attributed the 1947–48 objects to non-terrestrial craft. General Vandenberg is said to have rejected it for lack of physical proof. No original has surfaced in FOIA. Ufology treats the missing paper as the first official extra-terrestrial conclusion — and the first cover-up.", body: "Staff estimates are written to be shredded if the commander disagrees. That ordinary fate can look like a conspiracy. The surrounding fact is not ordinary: Sign was stood up because the objects were being reported by aircrews and radar, not by a newspaper hoaxer.", evidence: "Secondary testimony from Ruppelt and Sign veterans. No NARA folder contains a signed 1948 ET estimate.", sources: ["Edward J. Ruppelt memoir", "FOIA searches of early Air Force intelligence estimates"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 1948 },
  { id: "project-grudge", title: "Project Grudge", kicker: "1949–1951", subtitle: "Air Force · debunking turn", lede: "After Sign, Grudge was told to reduce the subject. The case load did not fall as neatly as the press releases.", summary: "Project Grudge replaced Sign with a mandate that most reports were error, hysteria, or hoax. The 1949 Grudge report said there was no threat and no surprise technology. Internal critics, including later Blue Book chief Ruppelt, called the climate anti-investigative. Grudge is the bureaucratic origin of ‘it was Venus’ as policy.", body: "A public-relations posture is not the same as a finding. Grudge still logged unknowns. When the 1952 Washington flap overwhelmed the system, Blue Book had to reopen a more serious desk. The file is the swing from curiosity to management.", evidence: "The Grudge report is public. Participant criticism is also on the record. There is no Grudge document that confesses a recovered craft.", sources: ["Project Grudge report, 1949", "Ruppelt, The Report on Unidentified Flying Objects"], lat: 39.823, lng: -84.049, place: "Wright-Patterson AFB, Ohio", country: "USA", year: 1949 },
  { id: "project-twinkle", title: "Project Twinkle", kicker: "1950–1951", subtitle: "Air Force / Cambridge · green fireballs", lede: "A camera-and-instrument study of the New Mexico green fireballs. It took little data and closed.", summary: "Project Twinkle tried to photograph the green fireballs that clustered over Los Alamos and other nuclear sites. Weather, funding, and a single instrument station produced almost no usable film. The fireballs stopped being an official crisis. Twinkle is the rare early program aimed at a physical, recurring phenomenon rather than anecdote.", body: "LaPaz thought some fireballs were not ordinary meteors. Twinkle never proved him right or wrong. Closing a poorly equipped study is not the same as solving the lights. The nuclear geography of the reports is the part that still reads oddly.", evidence: "Twinkle status reports are declassified. They show a thin instrument campaign, not a hidden success.", sources: ["Project Twinkle final reports", "LaPaz correspondence in Air Force files"], lat: 35.881, lng: -106.304, place: "Los Alamos, New Mexico", country: "USA", year: 1950 },
  { id: "moon-dust", title: "Moon Dust / Blue Fly", kicker: "1953–", subtitle: "Air Force · crashed-object recovery", lede: "A real recovery program for downed space objects. Ufologists argue it also bagged saucers.", summary: "Moon Dust and the related Blue Fly teams were Air Force units tasked to recover returned space debris and unknown crashed objects, including Soviet hardware. FOIA later confirmed the names. Nothing in the released tasking says ‘alien craft.’ The existence of a crash-recovery office is why every later retrieval story has a plausible bureaucratic home.", body: "A unit that picks up fallen satellites will also be first on a meteorite or a balloon payload. That does not prove it stored a disc. It does mean the Air Force practiced rapid, quiet recovery long before the 2020s whistleblowers used the word ‘legacy.’", evidence: "FOIA cables and unit mentions confirm Moon Dust. No released Moon Dust report identifies a non-human vehicle.", sources: ["FOIA Moon Dust cables (1980s releases)", "USAF foreign-technology recovery directives"], lat: 39.823, lng: -84.049, place: "Wright-Patterson AFB, Ohio", country: "USA", year: 1953 },
  { id: "hangar-18", title: "Hangar 18", kicker: "1948–", subtitle: "Wright-Patterson · alleged storage", lede: "The warehouse in the story of every American crash. The hangar number is folklore; the base is real.", summary: "Hangar 18 is the popular name for alleged UFO storage at Wright-Patterson, home of Air Technical Intelligence and later the Foreign Technology Division. Senators have asked; the Air Force has denied bodies in a hangar. The base did receive Blue Book material and foreign wreckage. The leap from ‘foreign technology’ to ‘non-human’ is the unresolved part.", body: "Wright-Patt is exactly where you would send unusual hardware. That geographic logic, plus Roswell, created Hangar 18. No authenticated photograph of a stored disc has come from the base. The file is a location, not an inventory list.", evidence: "Base histories confirm FTD/ATIC. Hangar-18-as-alien-morgue remains testimony and popular culture, not a declassified stocklist.", sources: ["Wright-Patterson AFB / ATIC-FTD histories", "Congressional inquiries as later reported"], lat: 39.823, lng: -84.049, place: "Wright-Patterson AFB, Ohio", country: "USA", year: 1948 },
  { id: "flying-saucer-working-party", title: "Flying Saucer Working Party", kicker: "1951", subtitle: "UK Ministry of Defence · DSI/JTIC", lede: "Britain’s first official saucer panel sat for months, then told ministers the objects were mistakes.", summary: "In 1951 the Directorate of Scientific Intelligence formed a Flying Saucer Working Party. Its secret report, released decades later, found no evidence of advanced vehicles and recommended no further special study. Some cases it reviewed would now be called radar-visual. The paper set a British tone of quiet dismissal until the later MoD desk.", body: "A five-person working party is not a deep technical investigation. The value of the file is documentary: London had an official UFO committee in 1951, then buried the product until the 2000s file releases.", evidence: "The DSI/JTIC report is in the UK National Archives. Membership and conclusions are not in dispute.", sources: ["UK National Archives, DSI/JTIC Flying Saucer Working Party", "MoD UFO file releases, 2000s"], lat: 51.503, lng: -0.127, place: "Whitehall, London", country: "UK", year: 1951 },
  { id: "project-magnet", title: "Project Magnet", kicker: "1950–1954", subtitle: "Canada · Wilbert Smith / Department of Transport", lede: "A Canadian engineer ran a small official study and wrote that a U.S. group already knew the saucers were real.", summary: "Wilbert Smith of the Department of Transport ran Project Magnet to study magnetic and UFO reports. A 1950 memo, later released, said a U.S. source told him flying saucers existed and were the most secret subject in America. Canada closed Magnet without a public ET finding. The memo is a primary; the unnamed American source is not.", body: "Smith’s later public lectures went further than his government paper. Project Second Storey sat alongside Magnet as a more sceptical committee. Canadian files are thinner than Blue Book but they are official. The 1950 memo is the sentence everyone quotes.", evidence: "The Smith memo and Magnet reports are public via Library and Archives Canada. The ‘secret U.S. group’ is hearsay inside a real memo.", sources: ["Wilbert Smith memo, 21 Nov 1950", "Project Magnet reports, Department of Transport"], lat: 45.421, lng: -75.697, place: "Ottawa", country: "Canada", year: 1950 },
  { id: "second-storey", title: "Project Second Storey", kicker: "1952–1954", subtitle: "Canada Defence Research Board", lede: "Ottawa’s quieter UFO committee, set up to keep Magnet from running ahead of the evidence.", summary: "Project Second Storey was a Defence Research Board committee that collected Canadian reports while Magnet chased instruments. Minutes show scientists asking for better data and not getting it. The committee faded. It is the Canadian cousin of Grudge: a real committee, modest conclusions, incomplete instruments.", body: "Second Storey matters because it proves Ottawa did not treat the 1952 wave as purely American newspaper copy. The minutes are dry. Dry is useful.", evidence: "Committee minutes and correspondence in Library and Archives Canada.", sources: ["Project Second Storey minutes", "Library and Archives Canada UFO collections"], lat: 45.421, lng: -75.697, place: "Ottawa", country: "Canada", year: 1952 },
  { id: "condign", title: "Project Condign", kicker: "1997–2000", subtitle: "UK Defence Intelligence · UAPs in the UK ADR", lede: "A secret MoD study blamed many British UAPs on plasma — and still treated them as an air-defence nuisance.", summary: "Project Condign, completed in 2000 and released in 2006, reviewed UK air-defence UAP reports. It argued that some unknowns were rare atmospheric plasma that could interfere with aircraft systems. It did not claim aliens. It did say the phenomena could be a defence issue. Nick Pope and others noted the study was done without telling the public desk.", body: "Condign is the last large British official paper. Its plasma language is speculative. Its existence is not. After Condign, the MoD closed the UFO desk. The 2008–13 file dumps are the aftermath.", evidence: "The redacted Condign report is in the UK National Archives. Authorship was later associated with a Defence Intelligence contractor study.", sources: ["MoD, UAPs in the UK Air Defence Region (Condign, 2000)", "UK National Archives release, 2006"], lat: 51.503, lng: -0.127, place: "Whitehall, London", country: "UK", year: 2000 },
  { id: "geipan", title: "GEPAN / SEPRA / GEIPAN", kicker: "1977–", subtitle: "CNES · French official UAP desk", lede: "France kept a civil-space UFO office when most countries closed theirs. The files are public.", summary: "CNES opened GEPAN in 1977, later SEPRA, now GEIPAN, to study unexplained aerospace phenomena. Trans-en-Provence and Valensole sit in its files. GEIPAN publishes case notes, not ET conclusions. It is the longest-running open Western official desk besides the post-2017 U.S. offices.", body: "A public scientific office can still be timid. GEIPAN’s value is procedure: gendarmerie reports, physical-trace work, and a classification scheme. Contact claims are not its product. The paper is.", evidence: "The GEIPAN site hosts thousands of case files. Institutional history is documented by CNES.", sources: ["GEIPAN https://geipan.fr/", "CNES historical notes on GEPAN/SEPRA"], lat: 43.527, lng: 1.503, place: "Toulouse", country: "France", year: 1977 },
  { id: "cometa", title: "COMETA report", kicker: "1999", subtitle: "France · retired-generals study", lede: "A private French committee of officers and engineers argued UAPs were a real, possibly extra-terrestrial, issue.", summary: "COMETA, a private group including retired French generals, published a 1999 report concluding that the extra-terrestrial hypothesis deserved serious study and that France should coordinate with the United States. It was not a CNES paper. Skeptics called it advocacy. It remains the most senior European ‘this is real’ document of the 1990s.", body: "Retired rank is not a sensor. COMETA used GEIPAN cases and aviation reports. Its leap to ET is a judgment, not a discovery. The file’s force is who signed it, not new radar plots.", evidence: "The COMETA report is published. CNES did not adopt it as agency doctrine.", sources: ["COMETA, Les OVNI et la Défense (1999)", "French press and CNES commentary"], lat: 48.856, lng: 2.352, place: "Paris", country: "France", year: 1999 },
  { id: "setka", title: "Setka-AN / Setka-MO", kicker: "1978–1990", subtitle: "USSR Academy / Defence · Soviet UFO program", lede: "After Petrozavodsk, Moscow ran a dual civil-military study of anomalous phenomena.", summary: "The Soviet Academy of Sciences (Setka-AN) and the Ministry of Defence (Setka-MO) collected UFO and anomalous-phenomena reports from 1978 into the late 1980s. Petrozavodsk was a trigger. Results were mixed: many space launches, some unknowns. The program is the documented Soviet counterpart to Blue Book, not a rumour.", body: "Soviet secrecy makes the files uneven in the West. Fragments, veteran interviews, and later Russian publications confirm the structure. No released Setka paper says a craft was recovered at Dalnegorsk or elsewhere.", evidence: "Academy and MoD program descriptions as later published; TASS-era public cases; incomplete file dumps.", sources: ["Soviet Academy Setka program notes as later published", "Russian retrospectives on Setka-AN/MO"], lat: 55.755, lng: 37.617, place: "Moscow", country: "Russia", year: 1978 },
  { id: "operacao-prato-file", title: "Operação Prato", kicker: "1977–1978", subtitle: "Brazilian Air Force · Colares investigation", lede: "A named FAB operation photographed objects and logged injuries on the Amazon coast. Then it went quiet.", summary: "Operação Prato was the Brazilian Air Force response to the 1977 Colares wave: officers, cameras, medical notes, and a later interview in which Col. Uyrangê Hollanda confirmed the work. The photos and reports were classified, then partly released. It is the clearest Latin American military field investigation.", body: "An operation can be real and still not mean the objects were non-human. Prato’s paper trail is what most countries never generated: a named task force, a commander, and images. The shutdown is the conspiracy hook.", evidence: "Declassified FAB/Prato materials in the Arquivo Nacional; Hollanda interviews. No official ET conclusion in the released set.", sources: ["FAB Operação Prato files (declassified)", "Arquivo Nacional, Brazil — UFO series"], lat: -0.936, lng: -48.28, place: "Colares, Pará", country: "Brazil", year: 1977 },
  { id: "cefaa-office", title: "CEFAA", kicker: "1997–", subtitle: "Chile DGAC · official UAP committee", lede: "Chile’s civil-aviation authority kept an anomalous-phenomena committee and released Navy sensor video.", summary: "CEFAA, under Chile’s DGAC, collected military and civil UAP reports and in the 2010s released a Navy helicopter infrared case after years of study. It is one of the few official offices in the Americas that published a ‘not identified’ sensor file before the U.S. 2017 break.", body: "A small committee in Santiago does not have AARO’s budget. It did have chain-of-custody aviation reports. The 2014 Navy video is the public flagship. Identification remains open in CEFAA’s language.", evidence: "CEFAA case releases and DGAC institutional pages. The Navy video is public.", sources: ["CEFAA / DGAC Chile case publications", "Chilean Navy 2014 IR video file"], lat: -33.45, lng: -70.666, place: "Santiago", country: "Chile", year: 1997 },
  { id: "wilbert-smith-memo", title: "Smith memo", kicker: "1950", subtitle: "Canadian DOT · ‘classified two points higher than the H-bomb’", lede: "Smith wrote that a U.S. source put flying saucers above the hydrogen bomb in classification. The source is unnamed.", summary: "The 21 November 1950 memo by Wilbert Smith is short, specific, and unofficial in tone: saucers are real, the subject is classified above the H-bomb, and a small U.S. group is working it. It is not a U.S. document. It is a Canadian engineer’s note after conversations in Washington. That gap is the whole fight.", body: "If the memo is honest hearsay, it is an early pointer at a crash-study group. If Smith was spun, it is a cautionary primary. Either way it is a dated piece of paper, not a blog post.", evidence: "The memo is released. No matching 1950 U.S. classification guide has been produced that uses Smith’s phrasing.", sources: ["Wilbert B. Smith, memorandum 21 Nov 1950", "Library and Archives Canada"], lat: 38.907, lng: -77.037, place: "Washington, D.C.", country: "USA", year: 1950 },
  { id: "nicap-keyhoe", title: "NICAP / Keyhoe", kicker: "1956–1980", subtitle: "Washington · civilian pressure group", lede: "Donald Keyhoe’s NICAP pushed Congress and the Air Force with military witnesses — and was watched in return.", summary: "The National Investigations Committee on Aerial Phenomena, led by retired Marine Major Donald Keyhoe, collected service reports and demanded hearings. The Robertson Panel had already suggested watching clubs. FBI and CIA files on NICAP exist. NICAP’s board included prominent Washington names. It is the template for later advocacy groups.", body: "A lobby is not a sensor. NICAP’s archives still hold useful case work. The conspiracy angle is the surveillance of a lawful civilian committee that was asking for the same reporting the Navy now mandates.", evidence: "NICAP publications, Keyhoe’s books, and FBI/CIA file fragments on the organization.", sources: ["Donald Keyhoe, Flying Saucers from Outer Space", "FBI Vault NICAP / Keyhoe files"], lat: 38.907, lng: -77.037, place: "Washington, D.C.", country: "USA", year: 1956 },
  { id: "condon-committee", title: "Condon Committee", kicker: "1966–1968", subtitle: "University of Colorado · Air Force contract", lede: "The study that let the Air Force close Blue Book also left a trail of political mail.", summary: "The University of Colorado UFO study, led by physicist Edward Condon, recommended no further official work. A leaked memo by coordinator Robert Low suggested the trick was to appear objective while finding the subject wanting. Hynek and others called the process stacked. Some case chapters still listed unknowns, including RB-47.", body: "A negative institutional conclusion can sit beside unsolved cases in the same volume. That is the Condon file. The Low memo is the conspiracy exhibit; the unknowns in the appendices are the scientific remainder.", evidence: "The Condon Report is public. The Low memo was published in Look and is not denied as a document.", sources: ["University of Colorado, Scientific Study of Unidentified Flying Objects (1969)", "Look magazine, ‘The Condon Report’ controversy"], lat: 40.007, lng: -105.267, place: "Boulder, Colorado", country: "USA", year: 1966 },
  { id: "hynek-cufos", title: "Hynek / CUFOS", kicker: "1973–", subtitle: "Center for UFO Studies · the Air Force consultant flips", lede: "Blue Book’s scientific face left the project and said the methods had failed the data.", summary: "J. Allen Hynek spent years as the Air Force’s astronomer on Blue Book, then published The UFO Experience and founded CUFOS. He argued that a residue of cases was not explained by the official posture. CUFOS collected civilian investigations with more patience than Blue Book. Hynek did not claim a retrieved craft.", body: "A consultant’s conversion is not a leak of a hangar. It is an expert saying the filing system was the problem. That still matters as a critique of Robertson-to-Condon policy.", evidence: "Hynek’s books, CUFOS archives, and his identifiable Blue Book correspondence.", sources: ["J. Allen Hynek, The UFO Experience (1972)", "CUFOS case holdings"], lat: 42.045, lng: -87.688, place: "Evanston, Illinois", country: "USA", year: 1973 },
  { id: "vallee-control", title: "Vallée control system", kicker: "1969–", subtitle: "Jacques Vallée · interdimensional / control hypothesis", lede: "Vallée argued the phenomenon behaves less like explorers and more like a control system for human belief.", summary: "Jacques Vallée, after Passport to Magonia, proposed that UFOs overlap folklore, religious visions, and high technology — a control system, possibly interdimensional, not a simple ET survey. The idea undercuts both nuts-and-bolts crash retrieval and simple debunking. It is now a main rival hypothesis in serious ufology.", body: "A hypothesis is not a program. Vallée also logged physical-trace cases and, later, the Trinity 1945 claim. The control-system file is theoretical. It belongs on this desk because later official talk of ‘observables’ still assumes a vehicle in our airspace.", evidence: "Vallée’s published books and journals. No government paper adopts ‘control system’ as doctrine.", sources: ["Jacques Vallée, Passport to Magonia; The Invisible College", "Forbidden Science journals"], lat: 37.774, lng: -122.419, place: "San Francisco, California", country: "USA", year: 1969 },
  { id: "five-observables", title: "Five observables", kicker: "2017–", subtitle: "AATIP language · how the craft are said to behave", lede: "Elizondo and others listed five traits: sudden acceleration, hypersonic speed, no signature, transmedium, anti-gravity.", summary: "The ‘five observables’ became the post-2017 vocabulary for UAP that do not behave like aircraft. They are a field guide, not a proof of origin. Critics note that sensor artifacts can mimic several traits. The list still structures congressional briefings and AARO case categories.", body: "A list can smuggle a conclusion: if all five are true in one object, conventional craft are in trouble. If they are a grab-bag across different videos, they are a slogan. The file is the slogan that moved staffers.", evidence: "Public Elizondo/TTSA briefings and later hearing language. Not a declassified AATIP directive with that title.", sources: ["TTSA / Elizondo public briefings", "Congressional UAP hearing transcripts, 2022–23"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2017 },
  { id: "transmedium-uso", title: "Transmedium / USO", kicker: "1960s–", subtitle: "Objects that enter water without a splash", lede: "A subset of reports describes craft that move from air to sea. The Navy now uses the word transmedium.", summary: "Unidentified submerged objects — Shag Harbour, Catalina, Aguadilla, older USO logs — sit beside the new official term ‘transmedium.’ If a vehicle ignores the air-water boundary, it is not a Cessna. If the video is a bird and a wave, it is. The hypothesis is now in statute-adjacent language, not only in books.", body: "Water hides wreckage. That is why USO claims are hard to kill and hard to prove. The conspiracy version is an undersea legacy fleet. The modest version is: some sensor cases do not look like splashes.", evidence: "Named historical USO cases plus post-2017 Navy/AARO vocabulary. No public recovered transmedium vehicle.", sources: ["U.S. Navy UAP reporting guidance", "Historical USO case files (Shag Harbour, Aguadilla)"], lat: 43.494, lng: -65.713, place: "Shag Harbour, Nova Scotia", country: "Canada", year: 1967 },
  { id: "kona-blue", title: "Kona Blue", kicker: "2011", subtitle: "DHS proposal · unacknowledged SAP pitch", lede: "A Department of Homeland Security proposal, later named in reporting, sought SAP cover for UAP work after AAWSAP.", summary: "Kona Blue is the name attached to a DHS special-access proposal that would have continued Bigelow-related UAP and paranormal study after AAWSAP lost DIA funding. It was not approved as described. The paperwork, as reported, is the bridge from a funded DIA contract to the later ‘legacy program’ vocabulary.", body: "A rejected SAP is still a document. It shows what some insiders wanted to hide behind a compartment. It does not show that a craft was in the compartment.", evidence: "Media and later official references to a DHS SAP proposal; no public full prospectus with signatures fully unredacted.", sources: ["Reporting on the Kona Blue DHS proposal", "AAWSAP aftermath as described by Lacatski / Knapp"], lat: 38.9, lng: -77.016, place: "Washington, D.C.", country: "USA", year: 2011 },
  { id: "legacy-program", title: "Legacy program", kicker: "2023–", subtitle: "Whistleblower term · crash retrieval as a hidden enterprise", lede: "The word Congress now hears for a multi-decade retrieval effort that AARO says it cannot verify.", summary: "‘Legacy program’ is the 2020s name for an alleged continuing crash-retrieval and reverse-engineering enterprise, compartmented away from AARO. Grusch used the idea without a public program title. AARO’s historical report said it found no evidence. The fight is over whether AARO was allowed to look.", body: "A term can organize oversight even when the org chart is invisible. Legacy is that term. Without a contractor, a budget line, or a hangar, it remains an allegation with named believers.", evidence: "Hearing testimony and AARO Historical Record Report (Vol. 1). No public contract register entry titled Legacy.", sources: ["House Oversight UAP hearing, 2023", "AARO Historical Record Report, Volume 1"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2023 },
  { id: "uap-disclosure-act", title: "UAP Disclosure Act", kicker: "2023–2024", subtitle: "Schumer–Rounds · eminent domain for UAP materials", lede: "Senate language tried to force a records body and even seizure of recovered UAP from private hands. It was gutted.", summary: "The Schumer–Rounds UAP Disclosure Act, floated in the 2023 NDAA fight, proposed a presidential review board and eminent domain over recovered technologies of unknown origin. House negotiators stripped the strongest pieces. What passed was thinner reporting. The draft is still the most aggressive official text yet aimed at a hidden retrieval program.", body: "Law that does not pass still shows what Senate leadership thought might exist in private vaults. Eminent domain language is not written for swamp gas. The gutting is the counter-move.", evidence: "Legislative text and NDAA conference outcomes are public. No court has tested the eminent-domain clause because it did not become law as drafted.", sources: ["UAP Disclosure Act legislative text, 2023", "NDAA conference reports, FY2024"], lat: 38.89, lng: -77.009, place: "U.S. Capitol", country: "USA", year: 2023 },
  { id: "aaro-historical", title: "AARO Historical Record", kicker: "2024", subtitle: "Pentagon · Volume 1", lede: "AARO told the public it found no verifiable evidence of extra-terrestrial technology or a hidden retrieval program.", summary: "AARO’s Historical Record Report, Volume 1 (2024), reviewed decades of claims and said most resolved to ordinary objects, and that it could not verify a legacy crash program. Critics said witnesses were not properly reached. The report is the official rebuttal to Grusch in document form.", body: "An inspector’s report is only as good as its access. AARO says it had access. Whistleblowers say the compartments sit above AARO. Both statements can be printed. Only one can be right about a given hangar.", evidence: "The report is public on AARO’s site. Classified annexes, if any, are not.", sources: ["AARO Historical Record Report, Vol. 1 https://www.aaro.mil/", "DoD public affairs statements, 2024"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2024 },
  { id: "ttsa", title: "To The Stars", kicker: "2017–", subtitle: "TTSA · Mellon, Elizondo, Puthoff, DeLonge", lede: "A public company became the vehicle that walked Navy videos and AATIP into the New York Times.", summary: "To The Stars Academy mixed entertainment, advisory contracts, and the 2017 disclosure push. Tom DeLonge recruited Christopher Mellon, Luis Elizondo, Hal Puthoff, and others. TTSA promoted metamaterial claims and the three videos. It later receded as Congress took the issue. The company is a vector, not a sensor.", body: "Mixing a rock musician’s firm with Pentagon alumni created a credibility fight that still shadows Elizondo. The videos were later confirmed by the Pentagon regardless of TTSA’s stock story.", evidence: "TTSA SEC filings, the 2017 Times story, and Pentagon video authentication. Metamaterial extraordinary claims remain unverified in the open literature.", sources: ["New York Times, 16 Dec 2017", "TTSA public filings and statements"], lat: 33.02, lng: -117.06, place: "Encinitas, California", country: "USA", year: 2017 },
  { id: "nids", title: "NIDS", kicker: "1995–2004", subtitle: "National Institute for Discovery Science · Bigelow", lede: "Robert Bigelow’s private institute put scientists on Skinwalker Ranch and UAP before AAWSAP existed.", summary: "NIDS, funded by Robert Bigelow in Las Vegas, investigated cattle mutilations, ranch phenomena, and aviation UAP, and employed people who later appear in AAWSAP. It published some papers and kept more private. NIDS is the civilian ancestor of the DIA’s ranch-and-UAP contract.", body: "Private money can hire PhDs without FOIA. That is NIDS’s power and its limit. The public sees fragments. The later BAASS contract is the government echo.", evidence: "NIDS publications, Bigelow’s public statements, and later AAWSAP memoirs that name NIDS as precursor.", sources: ["NIDS papers and press notes", "Lacatski, Kelleher & Knapp, Skinwalkers at the Pentagon"], lat: 36.17, lng: -115.14, place: "Las Vegas, Nevada", country: "USA", year: 1995 },
  { id: "dird-papers", title: "DIRD papers", kicker: "2008–2010", subtitle: "DIA · 38 theoretical studies", lede: "AAWSAP commissioned papers on warp drives, metamaterials, and extra dimensions. The bibliography is public.", summary: "The Defence Intelligence Reference Documents produced under AAWSAP/BAASS asked contractors to think about advanced aerospace: wormholes, invisibility, novel materials. FOIA released titles and some papers. They are speculative physics, not field recoveries. They show what the program thought worth paying for.", body: "A bibliography can look like a shopping list for a captured craft — or like a futurist’s reading list. Both readings exist. The invoices were real.", evidence: "DIA DIRD list via FOIA; some full papers circulated. No DIRD is a lab report on a recovered vehicle.", sources: ["DIA DIRD bibliography (FOIA)", "BAASS / AAWSAP contract reporting"], lat: 38.871, lng: -77.056, place: "Pentagon / DIA, Arlington", country: "USA", year: 2008 },
  { id: "garry-nolan", title: "Garry Nolan", kicker: "2012–", subtitle: "Stanford · immunology, materials, UAP brains", lede: "A Stanford professor began looking at claimed UAP materials and at brains of close-encounter patients.", summary: "Garry Nolan has said he analyzed unusual materials brought by patients and intelligence contacts, and MRI patterns in some experiencers. He has been cautious about origin. His presence moved UAP talk into a medical-school register. Critics want peer-reviewed material identifications that have not fully arrived.", body: "A professor’s lab is not Hangar 18. Nolan’s file is the respectable-science bridge of the 2020s, with all the caveats that implies.", evidence: "Interviews, conference talks, and limited papers. No Stanford press release claiming extra-terrestrial alloy.", sources: ["Nolan interviews and Sol Foundation talks", "Stanford affiliation as publicly stated"], lat: 37.428, lng: -122.17, place: "Stanford, California", country: "USA", year: 2012 },
  { id: "atacama-mummy", title: "Atacama mummy", kicker: "2003 / 2018", subtitle: "La Noria, Chile · tiny skeleton", lede: "A six-inch mummified body was sold as an alien. Genome work said a human fetus with mutations.", summary: "The Atacama specimen, recovered in Chile’s nitrate desert, was marketed in UFO circles as a non-human. A 2018 genome paper concluded it was human, with gene variants linked to bone disease, likely a preterm infant. The contact claim collapsed in the lab. The file stays as a warning about bodies offered without context.", body: "Physical remains are the one kind of proof that genetics can close. Here it closed toward human. That does not police every other claimed biologic; it polices this one.", evidence: "Bhattacharya et al., Genome Research (2018); Chilean heritage-law controversy over the remains.", sources: ["Bhattacharya et al., Genome Research, 2018", "Chilean reports on the La Noria specimen"], lat: -20.91, lng: -69.51, place: "La Noria, Atacama", country: "Chile", year: 2003 },
  { id: "nazca-mummies", title: "Nazca ‘alien’ mummies", kicker: "2017–", subtitle: "Peru · three-fingered exhibits", lede: "Bodies with three fingers were presented as non-human. Peruvian prosecutors and scientists called fraud.", summary: "From 2017, Jaime Maussan and others exhibited small mummified bodies said to be found near Nazca, with three-fingered hands. Independent researchers and Peruvian authorities described assembled animal and human bones. Mexico’s Congress got a later show. The file is a live authenticity fight, not a closed extra-terrestrial find.", body: "A body on a table is not automatically a specimen. Provenance, permits, and CT-scans that fit known anatomy matter. Nazca already has enough real archaeology without new skeletons of unknown chain-of-custody.", evidence: "Peruvian Ministry of Culture statements; competing CT/forensic claims; no consensus peer-reviewed non-human result.", sources: ["Peruvian Ministry of Culture comments", "Forensic critiques of the Nazca mummy exhibits"], lat: -14.739, lng: -75.13, place: "Nazca, Ica", country: "Peru", year: 2017 },
  { id: "maussan-congress", title: "Maussan in Congress", kicker: "2023", subtitle: "Mexico City · congressional UAP hearing", lede: "Mexico’s Congress hosted a UAP hearing and was shown alleged non-human bodies. The spectacle split the room.", summary: "In September 2023 journalist Jaime Maussan presented alleged non-human corpses to Mexican lawmakers. Scientists later publicly disputed the bodies. The hearing still put UAP on an official Latin American agenda beside the U.S. hearings. It is a political event with a contested prop.", body: "A congress can be used as a stage. That is not the same as a lab result. The file is logged because it is now part of the international disclosure calendar.", evidence: "Hearing video; subsequent Mexican scientific and prosecutorial commentary on the remains.", sources: ["Mexican Congress UAP hearing, Sept 2023", "Mexican scientific critiques, 2023–24"], lat: 19.433, lng: -99.133, place: "Mexico City", country: "Mexico", year: 2023 },
  { id: "stargate-rv", title: "Stargate Project", kicker: "1978–1995", subtitle: "DIA / CIA · remote viewing", lede: "A real U.S. psychic-spying program. It is not a flying saucer. It is the adjacent black-world file.", summary: "Stargate (and predecessors Grill Flame, Center Lane, Sun Streak) funded remote viewing at SRI and Fort Meade until the CIA closed it in 1995 as insufficiently useful. Declassified files are extensive. Ufology links it because the same intelligence culture touched AAWSAP’s ‘phenomena’ brief. Psychic spies are documented; their UAP targeting is the rumour.", body: "A declassified parapsychology SAP shows that strange compartments existed. It does not show that viewers sketched a hangar at Groom. Treat the overlap as cultural, unless a tasking sheet says otherwise.", evidence: "CIA FOIA Stargate collection. Official close-out found no intelligence value sufficient to continue.", sources: ["CIA Stargate archive (FOIA)", "American Institutes for Research close-out, 1995"], lat: 39.108, lng: -76.771, place: "Fort Meade, Maryland", country: "USA", year: 1978 },
  { id: "montauk", title: "Montauk", kicker: "1980s–", subtitle: "Camp Hero, Long Island · claimed experiments", lede: "A closed Air Force station became the story of time travel, abducted children, and a chair.", summary: "Montauk lore, spreading from Preston Nichols and Al Bielek, claims that Camp Hero hosted psychological and time experiments tied to the Philadelphia Experiment. The real base had a SAGE radar. There is no declassified program that matches the chair-and-portal story. The file is American military gothic built on a real fence line.", body: "Abandoned SAGE sites attract narrative. Montauk’s is the loudest. It belongs here because it recycles Philadelphia and feeds later ‘secret Navy physics’ talk, not because a portal was demonstrated.", evidence: "USAF Camp Hero / Montauk AFB records. Nichols’ books are the primary for the extreme claims — not a reliable primary for a SAP.", sources: ["USAF / NPS Camp Hero records", "Preston Nichols, The Montauk Project (as claim, not confirmation)"], lat: 41.071, lng: -71.859, place: "Camp Hero, Montauk", country: "USA", year: 1980 },
  { id: "magenta-1933", title: "Magenta 1933", kicker: "1933", subtitle: "Lombardy · alleged Mussolini crash retrieval", lede: "A 1933 Italian crash story, later tied to a fascist secret bureau, resurfaced in 2023 hearings.", summary: "Documents circulated in Italian ufology describe a 1933 disc recovery near Magenta and a Cabinet RS/33. Grusch later alluded to a Mussolini-era retrieval that the U.S. obtained after the war. Italian researchers are split on authenticity. No wreckage is on public Italian inventory.", body: "If genuine, the file moves crash retrieval before Roswell and out of New Mexico. If forged, it is a tidy prequel. 1933 paper needs 1933 provenance, not 1990s photocopies alone.", evidence: "Circulating ‘RS/33’ documents of contested authenticity; Grusch hearing allusions; no Italian state confirmation of a stored craft.", sources: ["Italian UFO research on the 1933 Magenta claim", "U.S. hearing references, 2023"], lat: 45.47, lng: 8.88, place: "Magenta, Lombardy", country: "Italy", year: 1933 },
  { id: "highjump", title: "Operation Highjump", kicker: "1946–1947", subtitle: "U.S. Navy · Antarctic expedition", lede: "A huge Navy expedition to Antarctica. Later lore added Nazi saucers and Admiral Byrd’s secret diary.", summary: "Highjump was a real 1946–47 U.S. Navy operation to Greenland-scale Antarctica: ships, aircraft, Byrd in command, early shutdown after losses. Conspiracy versions add battles with unknown craft or a surviving Nazi base. The official after-action is about weather, ice, and training. No combat with discs is in the Navy report.", body: "Antarctica’s secrecy is geographic. Highjump’s size invited myth. Read the Navy report first; add saucers only if a primary appears.", evidence: "U.S. Navy Highjump reports. The ‘secret Byrd interview’ about a land beyond the pole is a later, disputed text.", sources: ["U.S. Navy, Report of Operation Highjump", "Byrd contemporaneous press, 1947"], lat: -77.85, lng: 166.69, place: "Ross Sea / Little America", country: "Antarctica", year: 1946 },
  { id: "paperclip-saucers", title: "Paperclip / Nazi saucer lore", kicker: "1945–", subtitle: "Operation Paperclip · disc stories on the side", lede: "America imported German engineers. A parallel folklore imported German flying discs that were never in the factories.", summary: "Operation Paperclip is documented: German specialists to U.S. Army and Air Force programs. Die Glocke, Haunebu, and Antarctic saucer fleets are not in those contracts. Wartime Germans did study tailless aircraft (Horten). The leap to operational discs is postwar myth, sometimes mixed with real Paperclip names.", body: "Real advanced-aircraft research plus secrecy equals a perfect surface for later UFO origin stories. Keep the Horten flying wing. Leave the bell unless a primary shows it.", evidence: "Paperclip administrative files are public in outline. Haunebu technical files are not in surviving German archives as operational programs.", sources: ["NARA Operation Paperclip records", "Horten flying-wing histories; sceptical reviews of Nazi-UFO literature"], lat: 32.386, lng: -106.38, place: "White Sands / Fort Bliss", country: "USA", year: 1945 },
  { id: "cattle-mutilations", title: "Cattle mutilations", kicker: "1973–", subtitle: "American West · unexplained livestock deaths", lede: "Ranchers found animals with bloodless cuts. FBI ran a thin study. UFOs, cults, and predators all got blamed.", summary: "From the early 1970s, western ranchers reported cattle dead with missing organs and apparently surgical cuts. Officer Gabe Valdez in New Mexico and later NIDS took it seriously. The FBI’s 1970s look was limited. Predators and scavengers explain many; a residue of cases still sits in county files beside helicopter and light reports.", body: "Mutes became part of the UAP-ranch bundle (Skinwalker, Dulce, AAWSAP). That bundle may be one phenomenon or several stacked. The animal is real; the operator is the argument.", evidence: "County sheriff reports; FBI mutilation file; NIDS ranch papers. No authenticated non-human tool mark in a peer-reviewed veterinary series.", sources: ["FBI cattle mutilation file", "New Mexico state police / Valdez reports"], lat: 36.81, lng: -107.0, place: "Dulce / Rio Arriba County", country: "USA", year: 1975 },
  { id: "crop-circles", title: "Crop circles", kicker: "1980–", subtitle: "Wiltshire · formations and circlemakers", lede: "Some formations were made by men with boards. A smaller set still draws instrument teams.", summary: "English crop circles exploded in the 1980s. Doug Bower and Dave Chorley admitted to hoaxing many. Complex later formations, including Chilbolton’s 2001 ‘face and code,’ kept the argument alive. Soil and node studies are contested. The file is half art movement, half genuine anomaly claim.", body: "A known hoax method does not mathematically close every formation. It does shift the burden. Official MoD interest was slight; the fields were never a SAP.", evidence: "Circlemaker admissions; Wiltshire police occasional notes; contested plant-node papers.", sources: ["Bower & Chorley interviews, 1991", "UK press archives on the Wiltshire formations"], lat: 51.178, lng: -1.826, place: "Wiltshire downs", country: "UK", year: 1980 },
  { id: "chilbolton", title: "Chilbolton formation", kicker: "2001", subtitle: "Hampshire · Arecibo reply in a field", lede: "A crop formation appeared to answer the Arecibo message beside a radio telescope. Too tidy for some; too detailed for others.", summary: "In August 2001 a face and a framed ‘Arecibo reply’ appeared in crops next to the Chilbolton radio observatory. Circlemakers can work at night. The match to the 1974 Arecibo pictogram is the hook. No telescope log recorded a matching signal. The file sits at the edge of crop-circle art and SETI folklore.", body: "Proximity to a radio telescope is either a clue or a choice of stage. Without a signal on tape, the wheat is still wheat.", evidence: "Aerial photographs; Chilbolton Observatory location; no published radio detection tied to the night of the formation.", sources: ["Contemporary UK coverage, Aug 2001", "Arecibo message (1974) comparison charts"], lat: 51.145, lng: -1.437, place: "Chilbolton, Hampshire", country: "UK", year: 2001 },
  { id: "ummo", title: "UMMO", kicker: "1966–", subtitle: "Madrid · a typed civilisation", lede: "Letters from ‘Ummites’ arrived in Spain for decades. A Madrid professor later said he invented them.", summary: "UMMO was a contact affair of precise, bureaucratic letters claiming origin on IUMMA, plus the San José de Valderas photos. José Luis Jordán Peña later admitted a hoax. Some followers did not accept the confession. UMMO is the most elaborate European contactee paper trail — and a lesson in document theatre.", body: "A confession does not retrieve every letter from every believer. It does explain the house style. Keep UMMO as sociology of ufology unless a physical Ummite artifact appears with provenance.", evidence: "The letter corpus; Peña’s later statements; photographic studies of Valderas.", sources: ["UMMO letter collections", "Jordán Peña statements on authorship"], lat: 40.417, lng: -3.704, place: "Madrid", country: "Spain", year: 1966 },
  { id: "valiant-thor", title: "Valiant Thor", kicker: "1957", subtitle: "Pentagon · claimed Venusian guest", lede: "A story says a human-looking visitor from Venus spent years under the Pentagon. The guest log does not.", summary: "According to later contactee literature, Commander Valiant Thor met Eisenhower, lived in the Pentagon, and offered technology. There is no 1957 White House or DoD paper that matches. The tale rides the real 1950s Washington UFO panic. It is filed as contactee mythology with a specific address.", body: "Naming a wing of the Pentagon does not put a Venusian in it. The file’s use is to show how contactee narrative colonized real buildings.", evidence: "No authenticated visitor badge, photograph, or memo. Primary sources are later books and lectures.", sources: ["Contactee literature on Valiant Thor", "Eisenhower presidential papers (no matching guest)"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 1957 },
  { id: "brookings", title: "Brookings Report", kicker: "1960", subtitle: "NASA-commissioned · proposed SETI social science", lede: "A NASA-funded study said discovering life could unsettle publics — and that some discoveries might be withheld.", summary: "The Brookings Institution’s 1960 report Proposed Studies on the Implications of Peaceful Space Activities included a short section on the discovery of extra-terrestrial life and possible social shock. It noted that some authorities might suppress a discovery. Ufology reads that sentence as a disclosure policy. It was a think-tank maybe, not an order.", body: "A contractor suggesting that discovery could be destabilizing is not a standing order to lie about saucers. It is, however, an early official-adjacent text that names withholding as a conceivable option.", evidence: "The Brookings report is public. The relevant passage is brief. No implementing NASA directive titled ‘withhold UFOs’ is attached to it.", sources: ["Brookings Institution, Proposed Studies… (1960)", "NASA contract history"], lat: 38.899, lng: -77.04, place: "Washington, D.C.", country: "USA", year: 1960 },
  { id: "cia-haines", title: "CIA Haines study", kicker: "1997", subtitle: "Studies in Intelligence · CIA and UFOs 1947–90", lede: "A CIA historian admitted the Agency used UFO reports as cover for the U-2 and Oxcart — and that this fed the myth.", summary: "Gerald Haines’ 1997 Studies in Intelligence article argued that more than half of UFO reports in the late 1950s–60s were actually U-2 or A-12 flights, and that CIA encouraged the Air Force to hide that. The piece is often cited as a confession of deception. It is also a claim that most of those reports were ours, not theirs.", body: "Using saucers as cover for spy planes is documented here by an Agency historian. That cuts two ways: it proves deception, and it offers a prosaic engine for a lot of western U.S. lights. It does not close Tehran, Rendlesham, or Nimitz.", evidence: "The Haines article is declassified and published. Flight-test geography matches many but not all of the cited years.", sources: ["Gerald K. Haines, CIA’s Role in the Study of UFOs, 1947–90", "CIA U-2 / Oxcart histories"], lat: 38.952, lng: -77.146, place: "CIA, Langley, Virginia", country: "USA", year: 1997 },
  { id: "fbi-vault", title: "FBI Vault UFO", kicker: "1947–", subtitle: "FBI · flying discs file", lede: "The Bureau’s public vault holds decades of saucer memos, including the Guy Hottel ‘three flying saucers’ note.", summary: "The FBI Vault UFO collection includes field reports, hoaxes, and the 1950 Guy Hottel memo describing an Air Force informant’s claim of three recovered saucers. The Bureau later called that memo uncorroborated. The vault is still a primary-source pile, not a conclusion. It shows Hoover’s people logged the subject.", body: "A memo can go viral because it says ‘recovered.’ The Hottel note is third-hand. Other Vault files are ordinary sighting reports. Read the whole folder, not the meme.", evidence: "FBI Vault, UFO and Hottel files, public. The Bureau’s own caveat on Hottel is posted.", sources: ["FBI Vault, UFO collection https://vault.fbi.gov/", "Guy Hottel memo, 1950"], lat: 38.895, lng: -77.025, place: "FBI Headquarters, Washington", country: "USA", year: 1947 },
  { id: "nuclear-correlation", title: "Nuclear correlation", kicker: "1948–", subtitle: "Weapons sites · lights over the stockpile", lede: "A long list of reports sits on ICBM fields, bomb factories, and carrier groups. Pattern is not yet proof of intent.", summary: "Researchers including Robert Hastings have compiled nuclear-site UAP reports: Hanford, Oak Ridge, Malmstrom, Minot, Loring, British Bentwaters, Soviet depots. Some have logs. The correlation is the argument for intelligence behind the lights. Alternative: those sites have more sensors, more guards, and more classified flights.", body: "A pattern can be targeting or sampling bias. The honest file keeps both. Missile-shutdown claims (Echo Flight) are the sharp end.", evidence: "Declassified security logs from named bases; Hastings’ witness set; official denials or silence on shutdowns.", sources: ["Robert Hastings, UFOs and Nukes", "FOIA missile-wing and AEC security fragments"], lat: 47.505, lng: -111.187, place: "Malmstrom AFB, Montana", country: "USA", year: 1967 },
  { id: "malmstrom-cover", title: "Echo Flight shutdown", kicker: "1967", subtitle: "Malmstrom AFB · missiles off alert", lede: "Officers say a UAP coincided with ten Minuteman missiles dropping offline. The complete packet is not public.", summary: "Robert Salas and others have described the 16 March 1967 Echo Flight shutdown at Malmstrom as a UAP event. Some documents confirm missiles dropped off alert; the cause in the open file is not a craft. The gap between a real anomaly in a missile wing and a briefed extra-terrestrial is the conspiracy.", body: "Nuclear command-and-control failures are investigated. If a light in the sky was written into that investigation, the public still has not been given the full memo. That is the live FOIA fight.", evidence: "Partial missile-wing records; Salas testimony; no released telex that says ‘UFO caused inhibit.’", sources: ["Salas public testimony and documents", "Malmstrom / 341st Strategic Missile Wing fragments"], lat: 47.505, lng: -111.187, place: "Malmstrom AFB, Montana", country: "USA", year: 1967 },
  { id: "disclosure-2001", title: "Disclosure Project 2001", kicker: "2001", subtitle: "National Press Club · Steven Greer", lede: "Dozens of military and intelligence witnesses sat at the Press Club and said the cover-up was real.", summary: "On 9 May 2001 Steven Greer’s Disclosure Project staged a National Press Club event with former officers describing craft, radar tracks, and secrecy oaths. Some witnesses were solid aircrew; some stories were older and thinner. The event is a landmark in advocacy. It did not produce a craft.", body: "A press conference is not a hearing under oath, but it is a public record of who was willing to sit at a table in 2001. Later congressional witnesses overlap only partly. The file is the roster.", evidence: "Event video and witness list. Individual claims still need their own primaries.", sources: ["National Press Club, Disclosure Project, 9 May 2001", "Witness statements as recorded"], lat: 38.903, lng: -77.032, place: "National Press Club, Washington", country: "USA", year: 2001 },
  { id: "greer", title: "Steven Greer", kicker: "1993–", subtitle: "CSETI / CE-5 · contact as a method", lede: "Greer argues the phenomenon can be called in — and that a breakaway group hides the energy technology.", summary: "Steven Greer founded CSETI, promoted CE-5 protocols, and pushed the Disclosure Project. Supporters credit him with gathering witnesses. Critics point at overclaim, paid events, and the leap from lights to a hidden energy economy. He is a vector in the modern disclosure movement, not a sensor owner.", body: "Advocacy mixes with field claims. Keep Greer’s witness list; test each name. CE-5 lights over a desert can be aircraft. They can also be the thing the desk exists to log.", evidence: "Public events, books, and the 2001 Press Club roster. No independent confirmation of a recovered energy device via Greer.", sources: ["Greer, Disclosure; CE-5 materials", "2001 National Press Club event record"], lat: 38.907, lng: -77.037, place: "Washington, D.C.", country: "USA", year: 1993 },
  { id: "eisenhower-greada", title: "Eisenhower / Greada", kicker: "1954", subtitle: "Edwards AFB · alleged treaty meeting", lede: "A story says Eisenhower vanished from Palm Springs to sign a treaty with occupants at Edwards. The press said a dentist.", summary: "On 20 February 1954 Eisenhower disappeared from a Palm Springs weekend. The official line was a dental emergency. Later lore put him at Edwards meeting non-human beings and signing the ‘Greada’ treaty. No White House log supports the desert landing. The dentist story is thin enough to keep the rumour alive.", body: "A missing night in a president’s calendar is catnip. Thin cover stories happen for health and for classified flights. Neither is a signed extra-terrestrial treaty. Demand a primary from Edwards or the White House Office.", evidence: "Palm Springs press pool, Feb 1954; later contactee/treaty literature. No 1954 Edwards after-action of a landing ceremony.", sources: ["Palm Springs contemporaneous press, 20–21 Feb 1954", "Later Greada treaty claims in UFO literature"], lat: 34.905, lng: -117.884, place: "Edwards AFB, California", country: "USA", year: 1954 },
  { id: "serpo", title: "Serpo", kicker: "2005", subtitle: "Alleged 12-year exchange mission", lede: "Anonymous posts described a U.S. team sent to planet Serpo. The paper trail begins on the internet.", summary: "In 2005 an anonymous ‘Anonymous’ posted the Serpo story: twelve Americans to a Zeta Reticuli world in the 1960s as an exchange. No 1960s NASA, USAF, or State document corroborates a missing team of that size. Serpo is late-period internet mythology wearing Project Blue Book clothes.", body: "Exchange-mission stories recycle Hill-map astronomy and military-mission structure. Without names that check out in 1960s personnel files, Serpo stays on the fiction side of this desk.", evidence: "Web postings and later self-published expansions. No FOIA hit on ‘Serpo’ as a real program name.", sources: ["Serpo.org postings, 2005–", "Personnel-file negative searches as reported by researchers"], lat: 32.852, lng: -106.107, place: "Holloman AFB, New Mexico", country: "USA", year: 2005 },
  { id: "solar-warden", title: "Solar Warden", kicker: "2000s", subtitle: "Claimed secret space fleet", lede: "Internet lore describes a U.S.-led off-world navy. Budget documents describe satellites, not destroyers at Saturn.", summary: "Solar Warden is the popular name for an alleged secret space program with cruisers in deep space. It collides with the real classified NRO satellite world and with breakaway-civilization talk. No contractor earnings call, shipyard, or leaked hull number has checked out. The NRO is secret enough without a navy at Jupiter.", body: "Classified space is real. A manned secret fleet with decades of logistics is a much larger claim. Size is the skeptic’s friend here.", evidence: "No primary. Contrast with declassified NRO/CIA satellite histories that already explain a lot of ‘secret space.’", sources: ["NRO / CIA overhead reconnaissance histories", "Solar Warden as internet-era claim"], lat: 33.92, lng: -118.38, place: "Los Angeles AFB / NRO west", country: "USA", year: 2006 },
  { id: "breakaway", title: "Breakaway civilization", kicker: "2000s", subtitle: "Dolan hypothesis · a parallel technical society", lede: "Richard Dolan’s phrase for a classified world that kept the good technology and left the public behind.", summary: "‘Breakaway civilization’ names the idea that crash retrieval plus sixty years of black budgets produced a parallel aerospace culture. It is a historical hypothesis, not a program title. It tries to make sense of the gap between Nimitz kinematics and public aircraft. It can also over-explain secrecy that is just weapons work.", body: "The hypothesis is useful as a question: where did the money go? It is dangerous as a conclusion without a hangar. This desk keeps it as a frame, not a finding.", evidence: "Dolan’s published argument; black-budget reporting in the unclassified press. No org chart of a breakaway state.", sources: ["Richard Dolan, essays on breakaway civilization", "Unclassified U.S. black-budget overviews"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2010 },
  { id: "hitchhiker-effect", title: "Hitchhiker effect", kicker: "1996–", subtitle: "Skinwalker-associated · phenomena that follow you home", lede: "Investigators at the Utah ranch described poltergeist-like effects that tagged along to their houses.", summary: "NIDS and later BAASS personnel reported that after time at Skinwalker Ranch, some families experienced lights, creatures, or household disturbances at home — the ‘hitchhiker.’ It is in Skinwalkers at the Pentagon. Conventional psychology offers expectation and stress. The program treated it as contagious phenomena. That claim is why AAWSAP was wider than aviation.", body: "If true, UAP is not only aerospace. If false, it is folklore attached to a DIA contract. Either way it explains why later whistleblowers talk about more than tic-tacs.", evidence: "Memoir and interview material from BAASS/NIDS personnel. No public medical series.", sources: ["Lacatski, Kelleher & Knapp, Skinwalkers at the Pentagon", "NIDS ranch notes as later described"], lat: 40.258, lng: -109.682, place: "Uintah Basin, Utah", country: "USA", year: 1996 },
  { id: "cryptoterrestrial", title: "Cryptoterrestrial hypothesis", kicker: "2006–", subtitle: "Mac Tonnies / later revival · they are already here", lede: "The idea that the others are a hidden terrestrial culture, not visitors from Zeta Reticuli.", summary: "Mac Tonnies’ cryptoterrestrial hypothesis, later echoed in some 2020s discussion, says the phenomenon may be an indigenous non-human or hidden human culture on Earth — underground, undersea, or disguised. It borrows from folklore, USOs, and the failure of SETI-style visiting-fleet evidence. It is unproven and currently fashionable again.", body: "A hypothesis that needs no starship is attractive when starships are missing. It is also hard to falsify. Keep it labelled as speculation with a library, not a detection.", evidence: "Tonnies’ book and later popular revivals. No biological or archaeological type specimen.", sources: ["Mac Tonnies, The Cryptoterrestrials", "Later secondary discussions in UAP media"], lat: 39.1, lng: -94.58, place: "Kansas City, Missouri", country: "USA", year: 2006 },
  { id: "earthlights", title: "Earthlights / tectonic strain", kicker: "1982–", subtitle: "Persinger / Devereux · geology as a light source", lede: "A prosaic-strange theory: rocks and faults make lights that brains then turn into craft.", summary: "Michael Persinger’s tectonic-strain theory and Paul Devereux’s earthlights argue that some UFOs are geophysical lights, sometimes inducing hallucinations. Hessdalen is a test bed. The theory explains clusters on faults better than it explains F-18 FLIR videos. It belongs on the desk as the serious alternative to both ET and hoax.", body: "If plasma can lock a missile wing or a jet, it is still a defence problem. Condign reached for a similar lever. The kinematics of Nimitz remain a stretch for earthquake lights.", evidence: "Published tectonic-strain papers; Hessdalen measurements; critiques from aviation-case researchers.", sources: ["Persinger tectonic-strain papers", "Paul Devereux, Earth Lights"], lat: 62.793, lng: 11.191, place: "Hessdalen, Norway", country: "Norway", year: 1982 },
  { id: "metamaterials", title: "Metamaterials / TTSA artifacts", kicker: "2019–", subtitle: "Claimed crash metals · labs without a wreck", lede: "TTSA raised money to study alleged UAP materials. Peer-reviewed smoking guns have not followed.", summary: "To The Stars and associated researchers publicized bits of metal said to be from crashes, with unusual isotope or layering claims. Independent replication has been thin. Artifacts without chain of custody are just metal. The file is the materials side of disclosure theatre.", body: "A layered magnesium sample can be terrestrial and still weird. Weird is not a starship. Nolan and others have asked for better provenance. That request is the correct bureaucratic move.", evidence: "TTSA statements; limited analyses circulated; no consensus materials-science paper identifying non-terrestrial manufacture.", sources: ["TTSA metamaterial announcements", "Independent materials critiques"], lat: 33.02, lng: -117.06, place: "Encinitas, California", country: "USA", year: 2019 },
  { id: "odni-2021", title: "ODNI UAP report", kicker: "2021", subtitle: "Office of the Director of National Intelligence", lede: "The first modern all-source UAP assessment to Congress: 144 reports, 1 explained, the rest open.", summary: "The June 2021 ODNI Preliminary Assessment on UAP, driven by the UAP Task Force, told Congress that most of 144 reports remained unexplained and that the objects could pose a flight-safety and possibly a national-security issue. It did not say extra-terrestrial. It ended the laugh track in official language.", body: "A thin report can still change a town. This one created AARO’s runway. Later annual reports added numbers and still few identifications.", evidence: "The ODNI PDF is public. Subsequent DNI/AARO annual reports continue the series.", sources: ["ODNI, Preliminary Assessment: UAP, 25 June 2021", "UAP Task Force reporting"], lat: 38.94, lng: -77.2, place: "ODNI, McLean, Virginia", country: "USA", year: 2021 },
  { id: "uaptf", title: "UAP Task Force", kicker: "2020–2021", subtitle: "ONIand successors · the desk between AATIP and AARO", lede: "The Navy-driven task force that turned pilot reports into the 2021 assessment.", summary: "The UAP Task Force, established in 2020 under the Deputy Secretary of Defense, standardized reporting and fed ODNI. It was the bridge from AATIP lore to AARO bureaucracy. Some members later became critics of AARO’s scope. The org chart is public; the case files are not.", body: "Task forces are how Washington admits a problem without admitting a conclusion. The UAPTF did that job. Grusch’s later complaint is that the real files never entered that inbox.", evidence: "DoD UAPTF establishment memos; ODNI 2021 report. Case-level data remain largely unreleased.", sources: ["DoD UAP Task Force public statements", "ODNI 2021 assessment"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2020 },
  { id: "nasa-uap-panel", title: "NASA UAP panel", kicker: "2022–2023", subtitle: "NASA independent study", lede: "NASA convened scientists, said the stigma was the problem, and appointed a UAP research director.", summary: "NASA’s independent UAP study team, reporting in 2023, found no evidence of extra-terrestrial origin in the data it had, called for better unclassified sensors, and noted stigma as a reporting barrier. It is a civilian-science counterpart to AARO. It did not hunt hangars.", body: "NASA’s brand on a UAP panel mattered more than its dataset. The recommendation was: better cameras, less laughter. That is a modest official position, not disclosure.", evidence: "NASA UAP Independent Study Team report, 2023, public.", sources: ["NASA UAP Independent Study Team report, 2023", "NASA press briefing, Sept 2023"], lat: 38.883, lng: -77.016, place: "NASA HQ, Washington", country: "USA", year: 2023 },
  { id: "galileo-project", title: "Galileo Project", kicker: "2021–", subtitle: "Harvard / Avi Loeb · open UAP & interstellar science", lede: "Avi Loeb’s project tries to put UAP and interstellar objects on instruments, not anecdotes.", summary: "The Galileo Project at Harvard, led by Avi Loeb, builds instruments to hunt UAP and study interstellar objects like ʻOumuamua. It is openly extra-terrestrial-curious and controversial inside astronomy. It is the academic mirror of AARO: sensors first, origin later.", body: "A university project can still overclaim (see IM1 spherules). It can also force the subject into a lab notebook. That is its use on this desk.", evidence: "Project papers and instrument descriptions; debates in the astronomical press.", sources: ["Galileo Project, Harvard", "Loeb public papers on ʻOumuamua"], lat: 42.377, lng: -71.117, place: "Cambridge, Massachusetts", country: "USA", year: 2021 },
  { id: "oumuamua", title: "ʻOumuamua", kicker: "2017", subtitle: "Interstellar object · odd acceleration", lede: "The first known interstellar visitor accelerated without a visible comet tail. Loeb asked if it was a craft.", summary: "ʻOumuamua passed in 2017 with a non-gravitational acceleration and no clear outgassing. Most astronomers prefer a natural explanation (hydrogen ice, dust, shape). Loeb floated a thin lightsail. It is not a UAP in the Navy sense. It is the SETI-adjacent shock that landed in the same cultural window as the 2017 Times story.", body: "An interstellar oddity plus a UAP wave makes a mood, not a single phenomenon. Keep the datasets apart. The mood still fed disclosure politics.", evidence: "IAU / Pan-STARRS discovery data; Nature and ApJ papers; Loeb’s popular argument.", sources: ["Meech et al., ʻOumuamua discovery papers", "Loeb, Extraterrestrial (as hypothesis)"], lat: 20.707, lng: -156.257, place: "Haleakalā, Hawaii", country: "USA", year: 2017 },
  { id: "im1-spherules", title: "IM1 spherules", kicker: "2014 / 2023", subtitle: "Pacific · claimed interstellar meteor fragments", lede: "Loeb’s team dredged spherules from a 2014 fireball path and argued some were interstellar, possibly technological. Other scientists said contamination.", summary: "CNEOS meteor CNEOS 2014-01-08 (IM1) was later called possibly interstellar. A 2023 Galileo-related expedition recovered spherules from the seafloor near Papua. Critics argued industrial contamination and uncertain trajectory. The fight is live in the literature. It is a materials claim, not a saucer.", body: "Seafloor metal is the kind of thing labs can argue about forever. Until a consensus paper holds, IM1 is an open scientific dispute parked next to UAP because Loeb parked it there.", evidence: "CNEOS catalog; expedition preprints; published critiques of terrestrial contamination.", sources: ["CNEOS 2014-01-08 catalog entry", "Galileo Project IM1 expedition preprints and critiques"], lat: -4.5, lng: 147.6, place: "Pacific near Papua New Guinea", country: "Papua New Guinea", year: 2023 },
  { id: "gofast-debate", title: "GoFast debate", kicker: "2015 / 2017", subtitle: "Navy video · speed illusion", lede: "The third Pentagon video. Skeptics say parallax; pilots say objects on the range.", summary: "GoFast, released with Gimbal and FLIR1, shows a small object over water. Independent analyses argued the apparent speed is a camera-plus-parallax effect. Navy aircrew from the Roosevelt deployments still describe objects that outpaced them on other nights. One video can be boring while the range remains strange.", body: "Debunking a clip is not the same as closing a deployment. Keep the kinematics math. Keep the aircrew statements. Do not let either erase the other.", evidence: "Pentagon-authenticated clip; public kinematic critiques; Roosevelt aircrew interviews.", sources: ["Pentagon GoFast video", "Mick West and counter-analyses; aircrew interviews"], lat: 30.22, lng: -79.85, place: "Off Jacksonville, Florida", country: "USA", year: 2015 },
  { id: "gimbal-glare", title: "Gimbal glare debate", kicker: "2015", subtitle: "IR rotation · object or camera artifact", lede: "The famous rotating saucer may be a glare. The radar picture behind it is the rest of the argument.", summary: "Gimbal’s rotation has been modelled as an infrared glare from a distant jet. Pilots on the radio still talk about a fleet. AARO has not published a full public close-out. The clip is the most-watched official UAP video and the most fought-over.", body: "If Gimbal is a jet, the 2014–15 Roosevelt incursions still need a ledger. If it is not, the glare model is incomplete. The file is the fight.", evidence: "Authenticated video; competing photometric models; no official frame-by-frame close-out in public.", sources: ["Pentagon Gimbal video", "AARO imagery page; public glare analyses"], lat: 30.22, lng: -79.85, place: "Off Jacksonville, Florida", country: "USA", year: 2015 },
  { id: "roosevelt-incursions", title: "Roosevelt incursions", kicker: "2014–2015", subtitle: "USS Theodore Roosevelt · ‘range fouling’", lede: "Navy pilots including Ryan Graves described daily objects on the Tidewater training ranges.", summary: "Before the clips had names, Roosevelt strike-group aircrew reported objects at 0.6–0.8 Mach staying on station for hours, fouling the W-72 and other ranges. Graves later testified. The Navy issued new reporting guidance. This is the operational problem that made UAP a safety issue, not a hobby.", body: "A safety report can move a bureaucracy faster than a philosophy. Graves’ ‘range fouling’ line did that. The objects’ identity is still the open file.", evidence: "Graves testimony; Navy 2019 UAP reporting guidance; Roosevelt deployment timelines.", sources: ["House UAP hearing, 26 July 2023 (Graves)", "U.S. Navy UAP reporting guidance, 2019"], lat: 36.97, lng: -76.01, place: "Virginia Capes operating areas", country: "USA", year: 2014 },
  { id: "fravor-testimony", title: "Fravor testimony", kicker: "2004 / 2023", subtitle: "Nimitz · under oath", lede: "The Tic Tac intercept, told to Congress under oath by the skipper who flew it.", summary: "Cmdr. David Fravor’s 2023 testimony restated the 2004 Nimitz intercept: a white tic-tac over a disturbed sea, rapid acceleration, Princeton radar support, later FLIR1. Under oath is the difference from a talk-show. AARO still has not publicly matched it to a known vehicle.", body: "Sworn aircrew plus radar plus a Pentagon video is the modern gold-standard stack. It is not a retrieval. It is why this desk exists in 2026.", evidence: "Hearing transcript; Princeton/Nimitz witness set; FLIR1 authentication.", sources: ["House Oversight Committee, 26 July 2023", "AARO / Pentagon FLIR1"], lat: 31.6, lng: -118.9, place: "Off San Diego", country: "USA", year: 2004 },
  { id: "mellon-drop", title: "Mellon video drop", kicker: "2017", subtitle: "Former USD(I) staff · how the clips left the building", lede: "Christopher Mellon has described walking Navy UAP videos toward public release. The Pentagon later confirmed them.", summary: "Former Deputy Assistant Secretary of Defense for Intelligence Christopher Mellon helped get FLIR1, Gimbal, and GoFast into the 2017 story. He has written that the system was not taking UAP seriously. His role is the respectable insider leak — of videos, not of a hangar.", body: "A former intelligence official moving files to journalists is a political act. The later official authentication is what locked the videos into the historical record.", evidence: "Mellon’s published accounts; Pentagon confirmation of the three videos.", sources: ["Christopher Mellon, Politico / later essays", "Pentagon video authentication, 2020"], lat: 38.907, lng: -77.037, place: "Washington, D.C.", country: "USA", year: 2017 },
  { id: "elizondo-title", title: "Elizondo title dispute", kicker: "2017–", subtitle: "AATIP leadership · Pentagon vs résumé", lede: "The Pentagon has parsed whether Luis Elizondo ‘ran’ AATIP. The videos and the resignation letter still happened.", summary: "After 2017 the Pentagon sometimes distanced itself from Elizondo’s exact job title while confirming AATIP existed. FOIA and later reporting have been messy. The dispute is used to attack the entire disclosure arc. Title-parsing does not un-authenticate Gimbal.", body: "Bureaucracies feud over who gets to claim a program. That feud is now part of the file. Readers should separate personnel fights from sensor data.", evidence: "Pentagon public-affairs statements; Elizondo’s resignation as reported; later FOIA on AATIP staffing.", sources: ["DoD public-affairs statements on Elizondo/AATIP", "Elizondo, Imminent (as memoir)"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2017 },
  { id: "kirkpatrick", title: "Kirkpatrick / AARO", kicker: "2022–2023", subtitle: "First AARO director · the sceptic inside the building", lede: "Sean Kirkpatrick ran AARO, clashed with whistleblowers, and left arguing the extra-terrestrial claims were a social movement.", summary: "Sean Kirkpatrick, AARO’s first director, publicly said most cases resolve and that some crash-retrieval claims were recycled folklore. He later wrote that a narrative had outrun the data. Whistleblowers said AARO was a clearing house without access. The personality fight is now part of UAP oversight.", body: "An office can be honest and still under-scoped. Kirkpatrick’s papers are the official sceptic file. They need to be read, not only jeered.", evidence: "AARO public reports under Kirkpatrick; his later Scientific American-style essays; hearing follow-ups.", sources: ["AARO public reports, 2022–24", "Kirkpatrick post-directorship essays"], lat: 38.871, lng: -77.056, place: "Pentagon, Arlington", country: "USA", year: 2022 },
  { id: "burchett-hearings", title: "Burchett / Luna hearings", kicker: "2023–2024", subtitle: "House Oversight · open UAP sessions", lede: "A handful of House members kept UAP in open session when leadership would have preferred a closed room.", summary: "Representatives Tim Burchett, Anna Paulina Luna, and others pushed open hearings after Grusch. The sessions mixed strong aircrew with weaker props. Open oversight is the point of the file: classified briefings had not satisfied the members. Subpoena fights continue.", body: "Hearings are messy by design. The conspiracy version is that leadership blocks subpoenas to protect a contractor. The prosaic version is that classified SAPs are always hard to haul into a hearing room. Both can be true at once.", evidence: "Hearing transcripts and member statements. Subpoena outcomes are on the committee record.", sources: ["House Oversight UAP hearings, 2023–24", "Member letters on UAP subpoenas"], lat: 38.89, lng: -77.009, place: "U.S. Capitol", country: "USA", year: 2023 },
  { id: "gillibrand", title: "Gillibrand amendment", kicker: "2021–", subtitle: "Senate · statutory UAP office", lede: "Kirsten Gillibrand’s NDAA language is why AARO exists as law, not only as a press shop.", summary: "Senator Gillibrand’s amendments to the NDAA created a statutory UAP office with reporting lines intended to reach beyond a single service. The language was negotiated down over years but it is the legal skeleton of AARO. Disclosure as statute started here more than at the Press Club.", body: "If you want to know whether Washington ‘took it seriously,’ read the NDAA text, not a documentary. Gillibrand’s file is that text.", evidence: "NDAA UAP sections, FY2022–. Implementation is AARO’s public reporting.", sources: ["NDAA UAP provisions sponsored/negotiated by Sen. Gillibrand", "AARO authorizing language"], lat: 38.89, lng: -77.009, place: "U.S. Senate", country: "USA", year: 2021 },
  { id: "nj-drones-2024", title: "New Jersey drone wave", kicker: "2024", subtitle: "Northeast U.S. · unresolved incursions", lede: "Weeks of drone reports over New Jersey and neighbouring states, after Langley, with no public owner.", summary: "In late 2024, police, politicians, and residents across New Jersey and the wider Northeast reported large drones at night. Federal agencies offered partial explanations (legal drones, manned aircraft, hysteria) without a single owner for the more credible clusters. Coming after Langley, the wave read as an airspace-control failure.", body: "A drone panic can be mostly misidentification and still contain a few real incursions. The official muddle is the file. UAP offices were asked, then mostly ducked, calling it drones — unidentified drones.", evidence: "State police logs; FBI/DHS statements; no complete public identification of the more documented tracks.", sources: ["New Jersey State Police / local reports, 2024", "DHS / FBI comments on the drone wave"], lat: 40.22, lng: -74.76, place: "Central New Jersey", country: "USA", year: 2024 },
  { id: "chinese-balloon", title: "Spy balloon vs UAP", kicker: "2023", subtitle: "North American airspace · a known object in UAP clothing", lede: "The 2023 Chinese balloon showed how slowly NORAD can see a large slow object — and how fast the public says UFO.", summary: "In February 2023 a Chinese surveillance balloon crossed the U.S. and was shot down off South Carolina. Officials later said other balloon-like objects had been logged as UAP. The episode is a prosaic lesson and a sensor lesson: slow objects at odd altitudes were a hole in the picture. It is not a tic-tac.", body: "Using balloons to close the entire UAP set is the over-correction. Using them to explain a subset is mandatory. This file is the subset.", evidence: "DoD / NORAD balloon shoot-down briefings, Feb 2023; later statements on prior balloon UAP.", sources: ["DoD Chinese balloon briefings, Feb 2023", "NORAD public statements"], lat: 33.69, lng: -78.89, place: "Off Myrtle Beach, South Carolina", country: "USA", year: 2023 },
  { id: "black-vault", title: "The Black Vault", kicker: "1996–", subtitle: "John Greenewald · FOIA as a method", lede: "A civilian FOIA machine that has posted millions of pages of UFO/UAP documents the government already had.", summary: "John Greenewald’s Black Vault is not a theory. It is a reading room of FOIA releases: Blue Book extras, CIA, NSA crumbs, AATIP-adjacent files. Conspiracy on this desk often dies or hardens in those PDFs. The site is how a lot of the paper on the other files became public.", body: "Primary documents can still be redacted into mush. Greenewald’s contribution is volume and persistence. Read the PDFs before the thread.", evidence: "The Black Vault holdings; original FOIA letters. Authenticity is the agencies’ own releases.", sources: ["The Black Vault https://www.theblackvault.com/", "FOIA reading rooms (CIA, FBI, NSA, USAF)"], lat: 34.052, lng: -118.244, place: "Los Angeles, California", country: "USA", year: 1996 },
  { id: "uk-files-release", title: "UK MoD file dump", kicker: "2008–2013", subtitle: "National Archives · the British desk goes public", lede: "The Ministry of Defence transferred its UFO files and closed the public desk. Researchers are still reading.", summary: "Between 2008 and 2013 the UK released tens of thousands of MoD UFO pages to the National Archives — Rendlesham, Cosford, Calvine captions, Bonnybridge letters. Nick Pope had already been the public face of the desk. Condign had already been written in secret. The dump is the British Blue Book, late.", body: "A file release can be transparency or a garage sale. These PDFs still generate new finds (Calvine). They do not include a live SAP.", evidence: "UK National Archives UFO collections (DEFE series). Completeness of the most sensitive annexes is the open question.", sources: ["UK National Archives, MoD UFO files", "Nick Pope, Open Skies, Closed Minds (as memoir of the desk)"], lat: 51.5, lng: -0.126, place: "National Archives, Kew", country: "UK", year: 2008 },
  { id: "nick-pope", title: "Nick Pope", kicker: "1991–1994", subtitle: "MoD UFO desk · the public clerk", lede: "The civil servant who later said the British desk saw more than it was allowed to take seriously.", summary: "Nick Pope ran the MoD’s public UFO office in the early 1990s and later became a media advocate, arguing that some UK cases (Cosford, Rendlesham) were under-investigated. Critics call him a self-promoter. The desk existed; he sat at it. His memoir is a primary for the office culture, not for a hangar at Porton Down.", body: "A clerk can be right about process and wrong about a case. Pope is most useful on how Whitehall managed the subject — the Condign secrecy, the press lines — than as a sensor.", evidence: "MoD employment on the UFO desk is not seriously disputed; later interpretations are.", sources: ["Nick Pope, Open Skies, Closed Minds", "MoD UFO desk files, UK National Archives"], lat: 51.503, lng: -0.127, place: "Whitehall, London", country: "UK", year: 1991 },
  { id: "australian-release", title: "RAAF file release", kicker: "2000s", subtitle: "National Archives of Australia · official Australian paper", lede: "Australia quietly released RAAF UFO files covering Westall’s era, Tully, and later reports.", summary: "The RAAF kept UFO policy files now at the National Archives of Australia. They show a small official interest, a desire not to look like Blue Book, and case notes on Tully, Westall-period reports, and later lights. Australia did not run a public GEIPAN. The PDFs are still the country’s official spine.", body: "A thin archive is still an archive. Australasian cases on the map have somewhere to footnote. That is this file.", evidence: "NAA RAAF UFO policy and case files, public.", sources: ["National Archives of Australia, RAAF UFO files", "RAAF policy directives on unusual aerial sightings"], lat: -35.28, lng: 149.13, place: "Canberra", country: "Australia", year: 2003 },
  { id: "de-brouwer", title: "De Brouwer / Belgian Air Force", kicker: "1990", subtitle: "Belgian Defence · F-16 locks on the triangle", lede: "A general put his name on the Belgian wave’s radar plots. That is rarer than a blurry photo.", summary: "Major-General Wilfried De Brouwer, then chief of operations, publicly discussed the 1990 F-16 pursuit of the Belgian triangle and the police reports from Eupen. Belgian Defence released radar data. Skeptics offered helicopters and stars. A named air-force general is still the unusual part.", body: "Rank does not make an object extra-terrestrial. It makes the paper harder to call a tabloid. Belgium’s file is official and unfinished.", evidence: "Belgian Air Force radar releases; De Brouwer public statements; Eupen police log.", sources: ["Belgian Defence 1989–90 wave file", "De Brouwer interviews and later COMETA-adjacent remarks"], lat: 50.85, lng: 4.35, place: "Brussels", country: "Belgium", year: 1990 },
  { id: "hessdalen-project", title: "Project Hessdalen", kicker: "1983–", subtitle: "Norway · long-running instrument campaign", lede: "A valley with recurring lights got magnetometers and cameras instead of a press officer.", summary: "Project Hessdalen, initiated by Erling Strand and others, is one of the only long-term instrumental UAP/earthlight studies. It has recorded lights with structure and odd spectra. It has not identified a craft. It is the anti-conspiracy: open instruments, slow papers, no hangar.", body: "If every case were Hessdalen, this desk would be a geophysics blog. It is not. The project still shows what a non-military method looks like.", evidence: "Project Hessdalen technical reports and public data snippets.", sources: ["Project Hessdalen reports", "Østfold University College participation notes"], lat: 62.793, lng: 11.191, place: "Hessdalen, Trøndelag", country: "Norway", year: 1983 },
  { id: "narcap", title: "NARCAP", kicker: "1999–", subtitle: "Aviation safety · UAP as a cockpit hazard", lede: "A nonprofit treated unidentifieds as a pilot-safety problem years before the Navy’s 2019 guidance.", summary: "The National Aviation Reporting Center on Anomalous Phenomena, associated with Richard Haines (NASA Ames, retired), collected aircrew UAP reports as a safety dataset. It is the sober aviation-file counterpart to crash-retrieval drama. O’Hare 2006 sits in that tradition.", body: "Safety reporting is how UAP re-entered official language: not as aliens, as near-misses. NARCAP was early.", evidence: "NARCAP technical reports; Haines’ aviation-UAP papers.", sources: ["NARCAP reports", "Richard F. Haines aviation-UAP studies"], lat: 37.415, lng: -122.057, place: "Mountain View, California", country: "USA", year: 1999 },
  { id: "scu", title: "Scientific Coalition for UAP Studies", kicker: "2017–", subtitle: "SCU · Aguadilla and kinematics papers", lede: "A volunteer scientific group published a long analysis of the 2013 Aguadilla IR video.", summary: "SCU’s Aguadilla paper argued the Customs video did not match a bird, balloon, or conventional aircraft, including a water-entry without splash. Critics of the analysis exist. SCU is part of the post-2017 attempt to do unclassified technical work without a SAP. The paper is the file.", body: "Civilian kinematics can be wrong and still be the right genre. AARO’s job is to do this with better data. Until then, SCU is on the shelf.", evidence: "SCU Aguadilla report (public PDF); CBP video.", sources: ["SCU, Aguadilla analysis", "U.S. Customs and Border Protection 2013 IR video"], lat: 18.495, lng: -67.136, place: "Aguadilla", country: "Puerto Rico", year: 2018 },
  { id: "baass-report", title: "BAASS ten-month report", kicker: "2009", subtitle: "Bigelow / AAWSAP · the thick notebook", lede: "A contractor report to DIA, still largely unpublished, is said to hold the ranch, the cases, and the weird.", summary: "BAASS produced a large ten-month report for AAWSAP that insiders describe as thousands of pages of case work, ranch logs, and analysis. Fragments and descriptions circulate; the full report is not public. It is the rumoured encyclopedia behind Skinwalkers at the Pentagon.", body: "A missing contractor deliverable is the most boring possible smoking gun — and therefore plausible. FOIA has not produced the stack. That is the conspiracy: a paid report the public still cannot read.", evidence: "Contract existence is documented; full ten-month report not released. Memoirs describe its bulk.", sources: ["AAWSAP/BAASS contract reporting", "Skinwalkers at the Pentagon (description of the report)"], lat: 36.17, lng: -115.14, place: "Las Vegas, Nevada", country: "USA", year: 2009 },
  { id: "looking-glass", title: "Looking Glass", kicker: "1990s–", subtitle: "Claimed time-viewing system", lede: "A rumoured project to look forward and backward. It lives in the same drawer as Montauk.", summary: "‘Project Looking Glass’ appears in internet-era secret-space lore as a device that views probable futures, sometimes tied to Dulce or to alleged beneath-Groom labs. There is no FOIA hit that matches the brochure. It is filed as late mythology that attaches to real command-and-control names (Looking Glass is also a real airborne nuclear-command post).", body: "Name collision with the real Operation Looking Glass (airborne nuclear command) is how rumours gain a sheen of checkable fact. Keep the EC-135. Leave the time camera until a primary shows it.", evidence: "Real SAC Looking Glass histories vs. unsourced ‘Project Looking Glass’ web texts.", sources: ["USAF / SAC Looking Glass (ABNCP) histories", "Later internet-era Looking Glass claims"], lat: 41.132, lng: -95.912, place: "Offutt AFB, Nebraska", country: "USA", year: 1995 },
  { id: "ftd", title: "Foreign Technology Division", kicker: "1961–", subtitle: "Wright-Patterson · where you send the other side’s wreckage", lede: "The office that exploited Soviet hardware is the mundane home of every Hangar 18 story.", summary: "FTD (later NASIC) at Wright-Patterson reverse-engineered foreign — meaning Soviet and then everyone else’s — aircraft and missiles. If a non-human craft were exploited, this is the culture that would do it. That sentence is logic, not a document. FTD’s real inventory is MiGs, not tic-tacs, in the open record.", body: "The conspiracy is a one-word substitution: ‘foreign’ includes extra-terrestrial. The prosaic file is already extraordinary: exploitation of rival technology at industrial scale. Both readings use the same gate.", evidence: "FTD/NASIC public histories. No public FTD catalog line for a non-terrestrial vehicle.", sources: ["NASIC / FTD institutional histories", "Wright-Patterson AFB historical studies"], lat: 39.823, lng: -84.049, place: "Wright-Patterson AFB, Ohio", country: "USA", year: 1961 },
  { id: "egg-g", title: "EG&G", kicker: "1940s–", subtitle: "Nevada · the contractor at the gate", lede: "A real nuclear-and-security contractor. Lazar said they ran the badges at S-4.", summary: "EG&G (Edgerton, Germeshausen, and Grier) ran technical work at Nevada Test Site and related security. Bob Lazar named EG&G as part of the S-4 world. The company is real; the disc workshop is the unproven add-on. Contractors at Groom are the connective tissue of Area 51 stories.", body: "When a whistleblower names a contractor that is actually on the range, it sounds right even when the hangar is not shown. That is why EG&G belongs on the conspiracy map.", evidence: "EG&G Nevada Test Site history. Lazar’s employment claims remain unverified in payroll.", sources: ["Nevada Test Site contractor histories", "Lazar / Knapp interviews naming EG&G"], lat: 36.96, lng: -116.15, place: "Nevada Test Site", country: "USA", year: 1951 },
  { id: "skunk-works-uap", title: "Skunk Works UAP lore", kicker: "1980s–", subtitle: "Lockheed · Palmdale · rumoured exploitation", lede: "The shop that built the U-2 and Have Blue is always on the list of who would get the disc.", summary: "Lockheed’s Skunk Works is a documented special-projects culture (U-2, A-12, Have Blue, F-117). Later rumours put recovered UAP in Palmdale or in a quiet partnership with the Air Force. Ben Rich quotes about ‘the team at Lockheed’ knowing UFOs are real are disputed in wording. Capability plus secrecy equals a permanent pin.", body: "If you were hiding a craft, you might hide it where hiding aircraft is already the job. That remains a heuristic, not a stock photo.", evidence: "Skunk Works official histories; disputed Ben Rich quotations; no authenticated Palmdale disc.", sources: ["Lockheed Skunk Works histories", "Disputed Ben Rich remarks as circulated"], lat: 34.629, lng: -118.084, place: "Palmdale, California", country: "USA", year: 1988 },
  { id: "hopkins-intruders", title: "Hopkins / Intruders", kicker: "1981–1996", subtitle: "Budd Hopkins · abduction as a literature", lede: "A New York artist organized abduction reports into a pattern of examinations and missing time.", summary: "Budd Hopkins’ Missing Time and Intruders built the late-20th-century American abduction template: Greys, tables, scars, screen memories. Critics, including later later-day ufologists, attacked hypnosis as a method. The files he collected are still a sociological primary. They are not FAA data.", body: "Abduction literature is a stream of this desk separate from radar. It intersects when a named person (Hills, Walton) also has a police file. Hopkins sits at the center of the stream.", evidence: "Hopkins’ books and case notes as published; methodological critiques of hypnotic regression.", sources: ["Budd Hopkins, Missing Time; Intruders", "Later critiques of abduction-hypnosis method"], lat: 40.73, lng: -73.99, place: "New York, New York", country: "USA", year: 1981 },
  { id: "strieber-communion", title: "Communion", kicker: "1987", subtitle: "Whitley Strieber · the face on the cover", lede: "A novelist’s memoir put the Grey face in every supermarket and split ufology from experiencer culture.", summary: "Whitley Strieber’s Communion (1987) described visits at his cabin and made the Grey visor-face mass culture. Strieber has always complicated the ET reading. The book is not a government file. It is the reason ‘abduction’ left the subculture.", body: "A bestseller can be sincere and still be a poor sensor. Communion’s file is cultural — and therefore part of why Congress now hears the word ‘biologics’ without laughing, for better or worse.", evidence: "The memoir; cabin site as described; no corroborating radar of the visits.", sources: ["Whitley Strieber, Communion (1987)", "Later Strieber interviews on the uncertainty of origin"], lat: 41.7, lng: -74.87, place: "Cabin country, New York", country: "USA", year: 1985 },
  { id: "andreasson", title: "Andreasson Affair", kicker: "1967 / 1979", subtitle: "Massachusetts · a drawn examination", lede: "Betty Andreasson’s account, taken by Raymond Fowler, became one of the most illustrated American abduction files.", summary: "Betty Andreasson described entities in her Massachusetts home and a detailed onboard experience, published by Raymond Fowler with drawings. Hypnosis again. Religious imagery runs through the narrative. It is a high-detail experiencer file, not a cockpit recorder.", body: "Detail is not the same as corroboration. The Affair matters because later abduction stories quote its furniture. Keep it on the desk as literature with a named investigator.", evidence: "Fowler’s books and interview notes. No physical-trace consensus.", sources: ["Raymond Fowler, The Andreasson Affair", "Massachusetts contemporaneous notes as cited"], lat: 42.53, lng: -71.11, place: "South Ashburnham, Massachusetts", country: "USA", year: 1967 },
  { id: "linda-cortile", title: "Brooklyn Bridge / Cortile", kicker: "1989", subtitle: "Manhattan · claimed abduction over the East River", lede: "Hopkins published a case of a woman lifted from a 12th-floor window, supposedly seen from the bridge. It detonated in the community.", summary: "The Linda Cortile (Linda Napolitano) case, promoted by Budd Hopkins, claimed a 1989 abduction over the FDR Drive with diplomatic witnesses. Investigative journalists later tore at the witness chain. It is either the most public urban abduction or the most damaging cautionary tale in the field. The file is still radioactive.", body: "When a case becomes a referendum on an investigator, the object is already gone. Read the critiques with the original write-up.", evidence: "Hopkins’ published case; subsequent journalistic investigations; no NYPD file that matches a floating craft over the East River that night.", sources: ["Budd Hopkins, Witnessed", "Later investigative critiques of the Cortile case"], lat: 40.706, lng: -73.997, place: "Lower Manhattan", country: "USA", year: 1989 },
  { id: "peer-mack", title: "PEER / John Mack", kicker: "1990–2004", subtitle: "Harvard · psychiatrist of abductees", lede: "A Harvard psychiatrist treated abduction reports as real experiences and survived a faculty challenge.", summary: "John E. Mack of Harvard interviewed abductees, including the Ariel School children, and argued the experiences were not simple delusion. Harvard reviewed him and he kept his chair. Mack did not produce a craft. He did move the subject into a teaching hospital’s language, which is why this pin sits in Boston.", body: "Psychiatry can take a report seriously without authenticating an occupant. That distinction is Mack’s useful residue. Ariel is the field case; PEER was the office.", evidence: "Mack’s books; Harvard review reporting; Ariel interview tapes.", sources: ["John E. Mack, Abduction; Passport to the Cosmos", "Harvard faculty review coverage"], lat: 42.337, lng: -71.102, place: "Cambridge / Boston, Massachusetts", country: "USA", year: 1994 },
  { id: "contactee-giant-rock", title: "Giant Rock contactees", kicker: "1953–1970s", subtitle: "Mojave · van Tassel and the conventions", lede: "The American contactee movement had a physical headquarters: a boulder and a runway in the desert.", summary: "George Van Tassel hosted Giant Rock spacecraft conventions, built the Integratron nearby, and claimed contact with Solgonda. Adamski, Fry, and others shared the circuit. The FBI watched some of them. This is the folk religion of the saucer era, sitting on real BLM dirt. Later ‘Nordic’ lore starts here.", body: "Contactee culture is not Blue Book. It still shaped what witnesses thought they were allowed to see. The conspiracy angle is the Bureau’s interest in a desert club.", evidence: "Giant Rock convention records; Integratron as a standing building; FBI files on some contactees.", sources: ["Giant Rock convention programs", "FBI files on George Van Tassel / contactees"], lat: 34.333, lng: -116.389, place: "Giant Rock, California", country: "USA", year: 1954 },
  { id: "adamski", title: "George Adamski", kicker: "1952", subtitle: "Palomar Gardens · the original contactee photograph", lede: "Adamski’s Venusian and his hat-shaped photos became the template — and the punchline — of 1950s contact.", summary: "George Adamski claimed a 1952 meeting with a Venusian near Desert Center and produced photographs of a ‘scout ship.’ Astronomers and later ufologists called the photos fakes (a bottle cooler, a lamp). Adamski still lectured worldwide. The file is the prototype contactee package: photo, blonde visitor, peace message.", body: "A founding hoax, if that is what it is, still explains later imagery. Officials used Adamski to tar better cases. That tarring is part of Robertson-panel logic.", evidence: "Adamski photographs and books; multiple photographic debunkings; no supporting Palomar Observatory record.", sources: ["Adamski, Flying Saucers Have Landed", "Photographic critiques of the scout-ship stills"], lat: 33.713, lng: -115.4, place: "Desert Center, California", country: "USA", year: 1952 },
  { id: "shaver-mystery", title: "Shaver Mystery", kicker: "1945–", subtitle: "Richard Shaver / Ray Palmer · Deros under the earth", lede: "A pulp science story about underground tormentors leaked into UFO culture before Roswell had a name.", summary: "Richard Shaver’s stories of Deros in caverns, published by Ray Palmer in Amazing Stories, mixed claimed memory with fiction and built a pre-saucer subterranean myth. Palmer later boosted Arnold and Maury Island. The Shaver Mystery is the pulp root of Dulce-style underground bases.", body: "When later AFOSI officers fed Bennewitz underground-base stories, they were stirring a pot Palmer had already heated. That does not make Deros real. It makes the narrative old.", evidence: "Amazing Stories texts; Palmer’s later UFO editing. No geological survey of a Dero city.", sources: ["Amazing Stories, Shaver Mystery issues", "Ray Palmer editorial history"], lat: 43.038, lng: -87.906, place: "Milwaukee (Palmer’s Amazing)", country: "USA", year: 1945 },
  { id: "nsa-ufo", title: "NSA UFO documents", kicker: "1970s–", subtitle: "Fort Meade · heavily redacted COMINT", lede: "The NSA has released UFO-related documents that are almost entirely black ink. The existence of the file is the news.", summary: "FOIA to the National Security Agency produced a thin set of UFO documents, including COMINT-style reports with most lines redacted. Courts backed the redactions. The Agency has not published a UAP analytic product comparable to ODNI 2021. The black pages are a Rorschach for a signals-intelligence interest.", body: "Redaction can hide a secret or hide a nothingburger. NSA’s UFO FOIA set is famous because it looks like the former. Without the missing words, it is an interest, not a conclusion.", evidence: "NSA FOIA UFO releases; litigation records on continued classification.", sources: ["NSA UFO FOIA collection", "Federal court records on NSA UFO FOIA"], lat: 39.108, lng: -76.771, place: "Fort Meade, Maryland", country: "USA", year: 1980 },
];

console.log("conspiracy extra", files.length);
writeFileSync(
  "/workspace/src/lib/conspiracy-files-extra.ts",
  `import type { DeskFile } from "@/lib/desk-file";\n\nexport const CONSPIRACY_FILES_EXTRA: DeskFile[] = [\n${files.map(deskBlock).join(",\n")},\n];\n`,
);
